import{_ as a,o as e,c as i,a0 as t}from"./chunks/framework.Bmhw_dvp.js";const k=JSON.parse('{"title":"엔진만으로 돌리기","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/docs/cron"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/docs/cron"}],["meta",{"property":"og:title","content":"엔진만으로 돌리기"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"docs/cron.md","filePath":"docs/cron.md"}'),n={name:"docs/cron.md"};function o(p,s,l,r,h,c){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="엔진만으로-돌리기" tabindex="-1">엔진만으로 돌리기 <a class="header-anchor" href="#엔진만으로-돌리기" aria-label="Permalink to &quot;엔진만으로 돌리기&quot;">​</a></h1><p><strong>앱을 쓰신다면 이 장은 건너뛰셔도 됩니다.</strong> 부록입니다. 워커 화면에서 하나 추가하면 워커 파일 작성도 crontab 등록도 앱이 알아서 끝냅니다. 본선은 <a href="/docs/worker">워커</a>입니다.</p><p>여기부터는 <code>.dmg</code> 없이 <code>git clone</code>으로 엔진만 받은 경우입니다(<a href="/docs/install">설치</a> §엔진만). 화면이 없으니 워커 파일을 손으로 만들고, cron에 손으로 걸고, 결과를 셸에서 봅니다.</p><h2 id="_1-워커-파일-하나-만들기" tabindex="-1">1. 워커 파일 하나 만들기 <a class="header-anchor" href="#_1-워커-파일-하나-만들기" aria-label="Permalink to &quot;1. 워커 파일 하나 만들기&quot;">​</a></h2><p>프로젝트에 dira를 붙이는 데 필요한 건 이 파일 하나입니다. 필수는 <code>tick.sh</code>를 source하는 한 줄뿐입니다. <strong>이 파일이 놓인 위치가 곧 큐 루트입니다.</strong> <code>&lt;루트&gt;/workers/w1.sh</code>라면 <code>workers</code>의 부모가 루트라서, 어느 설정값에도 루트 경로를 적을 일이 없습니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Projects/myproject/.dira/workers</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Projects/myproject/.dira/workers/w1.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EOF&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">#!/bin/bash</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">. &quot;$HOME/Projects/dira/tick.sh&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Projects/myproject/.dira/workers/w1.sh</span></span></code></pre></div><p><code>tick.sh</code> 자체는 직접 실행하지 않습니다. 실행해 보면 rc=2로 거절하는데, 워커 파일이 어디 놓였는지를 모르면 루트도 알 수 없기 때문입니다. 진입점은 언제나 이 워커 파일 쪽입니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;루트&gt;/</span></span>
<span class="line"><span>  tickets/&lt;hash&gt;.md          &lt;- 큐. 평면이다</span></span>
<span class="line"><span>  personas/&lt;이름&gt;/PROFILE.md</span></span>
<span class="line"><span>  protocols/AGENTS.md</span></span>
<span class="line"><span>  workers/w1.sh w2.sh        &lt;- 워커. 여기 있는 파일 개수가 곧 동시성이다</span></span>
<span class="line"><span>  workers/runner.log logs/   &lt;- 디스패치 기록·세션별 출력</span></span></code></pre></div><p>페르소나와 프로토콜의 출발점이 필요하면 템플릿을 복사하세요. 없어도 그대로 돕니다. 페르소나 없는 평범한 에이전트가 티켓을 처리합니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Projects/dira/templates/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Projects/myproject/.dira/</span></span></code></pre></div><h2 id="_2-큐를-프로젝트-밖에-둘-때-—-ticket-cwd" tabindex="-1">2. 큐를 프로젝트 밖에 둘 때 — <code>TICKET_CWD</code> <a class="header-anchor" href="#_2-큐를-프로젝트-밖에-둘-때-—-ticket-cwd" aria-label="Permalink to &quot;2. 큐를 프로젝트 밖에 둘 때 — \`TICKET_CWD\`&quot;">​</a></h2><p>루트가 프로젝트 안에 있어야 할 이유는 없습니다. 여러 사람이 같은 큐에 붙는다면 마운트된 공유 드라이브(구글드라이브 등)에 <code>workers/</code>를 두고 cron이 그 경로를 가리키게 하세요.</p><p>세션은 기본적으로 루트의 부모에서 시작합니다(<code>&lt;프로젝트&gt;/.dira</code>가 루트면 <code>&lt;프로젝트&gt;</code>). 큐를 프로젝트 밖에 두면 이 기본값이 의미가 없어지니, <code>TICKET_CWD</code>로 작업 디렉터리를 직접 지정하시면 됩니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/Volumes/TeamShare/myteam/.dira/workers&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/Volumes/TeamShare/myteam/.dira/workers/w1.sh&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EOF&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">#!/bin/bash</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">TICKET_CWD=&quot;$HOME/Projects/myproject&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">. &quot;$HOME/Projects/dira/tick.sh&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/Volumes/TeamShare/myteam/.dira/workers/w1.sh&quot;</span></span></code></pre></div><p>마운트가 안 붙어 있으면 워커 파일 자체가 없습니다. cron이 그 경로를 불러도 실행할 스크립트가 없으니, 아무 로그도 안 남기고 조용히 실패합니다. 큐가 비어서 안 도는 게 아니라 파일이 없어서 안 도는 겁니다. &quot;빈 큐라 안 도는구나&quot;로 넘기지 마시고 <code>ls &quot;/Volumes/TeamShare/myteam/.dira/workers&quot;</code>로 워커 파일이 실제로 보이는지부터 확인하세요.</p><h2 id="_3-엔진-바꾸기-—-ticket-engine" tabindex="-1">3. 엔진 바꾸기 — <code>TICKET_ENGINE</code> <a class="header-anchor" href="#_3-엔진-바꾸기-—-ticket-engine" aria-label="Permalink to &quot;3. 엔진 바꾸기 — \`TICKET_ENGINE\`&quot;">​</a></h2><p>기본 엔진은 <code>claude -p</code>입니다. 워커는 프로젝트를 모르는 엔진 코드(<code>tick.sh</code>)를 불러 쓰는 자리라, 다른 CLI 에이전트로 바꾸는 것도 이 파일에 한 줄 얹으면 끝납니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/bash</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TICKET_ENGINE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{prompt}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/Projects/dira/tick.sh&quot;</span></span></code></pre></div><p><code>{prompt}</code> 자리에는 실행 직전 조립된 프롬프트가 들어갑니다. 응답 JSON의 실제 <code>session_id</code>로 frontmatter를 정정하는 단계는 <code>claude</code> 전용이라, 다른 엔진이면 그냥 건너뜁니다. 얹을 수 있는 값 전체는 <a href="/docs/ref-env">워커 환경변수</a>에 있습니다.</p><h2 id="_4-cron에-걸기-전-손으로-한-번-돌려-보기" tabindex="-1">4. cron에 걸기 전 손으로 한 번 돌려 보기 <a class="header-anchor" href="#_4-cron에-걸기-전-손으로-한-번-돌려-보기" aria-label="Permalink to &quot;4. cron에 걸기 전 손으로 한 번 돌려 보기&quot;">​</a></h2><p>cron부터 걸면 첫 실패가 인증 문제와 겹쳐 원인이 흐려집니다. 먼저 셸에서 왕복 한 번을 보세요.</p><p><code>dryrun</code>은 실행 없이 선정 결과와 조립된 프롬프트만 냅니다. 세션을 띄우기 전에 워커가 그 티켓을 정말 고르는지, 프롬프트가 뭘로 채워지는지 여기서 눈으로 확인하시면 됩니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/Projects/myproject/.dira/workers/w1.sh dryrun</span></span></code></pre></div><p>인자 없이 부르면 실제 1회 디스패치입니다. 워커가 티켓을 잡고, 세션을 띄우고, 그 세션이 끝날 때까지 기다립니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/Projects/myproject/.dira/workers/w1.sh</span></span></code></pre></div><p><code>list</code>는 열린 티켓 큐 상태(대기·할당됨·deps 대기)를 냅니다. 티켓이 큐에서 사라졌으면 방금 세션이 그것을 물고 끝낸 겁니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/Projects/myproject/.dira/workers/w1.sh list</span></span></code></pre></div><p>세 명령 모두 큐 전체를 보므로 같은 루트의 어느 워커 파일로 불러도 결과가 같습니다 (<a href="/docs/ref-cli">CLI</a> 참고).</p><h2 id="_5-crontab-두-줄" tabindex="-1">5. crontab 두 줄 <a class="header-anchor" href="#_5-crontab-두-줄" aria-label="Permalink to &quot;5. crontab 두 줄&quot;">​</a></h2><p>여기까지가 사람이 그 자리에서 워커를 부른 것입니다. 1분마다 저절로 돌게 하려면 cron에 등록합니다. cron은 로그인 키체인에 접근하지 못하므로 이 시점부터 장기 토큰이 필요하고 (<a href="/docs/auth">인증</a> §앱 없이 — 엔진만 쓸 때), 큐 루트가 클라우드 마운트라면 전체 디스크 접근 권한도 있어야 합니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>* * * * * $HOME/Projects/myproject/.dira/workers/w1.sh &gt;&gt; $HOME/Projects/myproject/.dira/workers/cron.log 2&gt;&amp;1</span></span>
<span class="line"><span>* * * * * sleep 30; $HOME/Projects/myproject/.dira/workers/w1.sh &gt;&gt; $HOME/Projects/myproject/.dira/workers/cron.log 2&gt;&amp;1</span></span></code></pre></div><p><code>crontab -e</code>로 위 두 줄을 넣으세요. <strong>워커 하나에 cron 두 줄</strong>입니다.</p><h3 id="두-줄인-이유" tabindex="-1">두 줄인 이유 <a class="header-anchor" href="#두-줄인-이유" aria-label="Permalink to &quot;두 줄인 이유&quot;">​</a></h3><p>cron이 낼 수 있는 가장 잔 단위는 분입니다(<code>man 5 crontab</code>). 30초마다 큐를 보게 하려면 :00에 한 줄, :30에 한 줄이 필요합니다. 두 번째 줄은 <code>sleep 30</code>으로 30초를 당긴 뒤 같은 워커를 부릅니다.</p><h3 id="한-줄에-로-붙이면-안-되는-이유" tabindex="-1">한 줄에 <code>;</code>로 붙이면 안 되는 이유 <a class="header-anchor" href="#한-줄에-로-붙이면-안-되는-이유" aria-label="Permalink to &quot;한 줄에 \`;\`로 붙이면 안 되는 이유&quot;">​</a></h3><p>워커는 동기 프로세스입니다. 셸이 <code>w1.sh</code>가 끝나야 <code>sleep 30</code>으로 넘어가니, 한 줄로 이으면 뒷반쪽이 앞 세션을 기다리게 됩니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 하면 안 되는 것</span></span>
<span class="line"><span>* * * * * w1.sh; sleep 30; w1.sh</span></span></code></pre></div><p>앞 호출이 티켓 하나를 30분짜리 세션으로 물었다면, 뒷반쪽은 30초 뒤가 아니라 30분 뒤에야 실행됩니다. 30초 폴링이 그냥 순차 실행이 되는 겁니다. 두 줄로 나눠야 cron 스케줄러가 각 줄을 독립된 프로세스로 :00과 :30에 각각 띄웁니다. 같은 분에 앞 실행이 아직 안 끝났으면 워커 락이 뒤 실행을 <code>SKIP</code>시키므로, 두 실행이 같은 티켓을 동시에 물 일은 없습니다.</p><h2 id="중지" tabindex="-1">중지 <a class="header-anchor" href="#중지" aria-label="Permalink to &quot;중지&quot;">​</a></h2><p>crontab에서 그 두 줄을 지우면 됩니다. 워커 파일까지 지우실 필요는 없습니다. 다시 등록할 때 그대로 씁니다.</p><h2 id="로그" tabindex="-1">로그 <a class="header-anchor" href="#로그" aria-label="Permalink to &quot;로그&quot;">​</a></h2><ul><li><code>&lt;루트&gt;/workers/runner.log</code> — 디스패치 진행 상황(선정·claim·SKIP 등)</li><li><code>&lt;루트&gt;/workers/logs/&lt;시각&gt;-&lt;워커&gt;-&lt;해시&gt;.log</code> — 세션별 실제 출력</li></ul><p>위 crontab 줄이 리다이렉트하는 <code>cron.log</code>는 워커 스크립트 자체의 표준출력·표준에러입니다. 정상 동작 중엔 대개 비어 있고, 셸 자체가 깨졌을 때만 여기 남습니다. 티켓이 실제로 어떻게 처리됐는지는 <code>runner.log</code>와 <code>logs/</code>에서 보시면 됩니다(<a href="/docs/logs">로그 읽는 법</a>).</p><p>안 도는 것 같으면 <a href="/docs/troubleshooting">트러블슈팅</a>을 보세요. 그 장은 화면에서 볼 자리를 먼저 주지만, 각 증상의 셸 확인 명령은 화면 없이도 그대로 씁니다.</p><p>다음은 <a href="/docs/ref-env">워커 환경변수</a>입니다.</p>`,45)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
